css:
:root {
  --bg-base: #0a0a0a;
  --bg-surface: #111111;
  --bg-card: #1f1f1f;
  --border: #2a2a2a;
  --text: #fafafa;
  --text-muted: #a1a1aa;
  --accent: #0ea5e9;
  --success: #22c55e;
  --danger: #ef4444;
  --warning: #f59e0b;

  /* Uma cor por fonte de receita — a mesma em pílula, gráfico e avatar. */
  --src-empresa: #0ea5e9;
  --src-impressionart: #8b5cf6;
  --src-moto: #f59e0b;
  --src-mos: #22c55e;

  --fonte: 'Manrope', sans-serif;
  --fonte-titulo: 'Sora', sans-serif;
  --fonte-mono: 'JetBrains Mono', monospace;
}

body { background: var(--bg-base); color: var(--text); font-family: var(--fonte); }

/* Número em tabela, card ou badge nunca "dança" ao atualizar. */
.bs-num { font-variant-numeric: tabular-nums; }

.bs-cads { width: min(420px, 100%); display: flex; flex-direction: column; gap: 10px; }

.bs-cad { padding: 14px; border: 1px solid var(--border); border-radius: 10px; background: var(--bg-base); }
/* Vermelho queimado: marca o atraso sem transformar o card em alarme. */
.bs-cad-atraso { border-color: #7f1d1d; }

.bs-cad-topo { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; }

.bs-cad-av {
  display: grid; place-items: center; flex-shrink: 0;
  width: 36px; height: 36px; border-radius: 10px;
  font-family: var(--fonte-titulo); font-size: 13px; font-weight: 700;
  color: var(--bg-base); background: var(--cor);
}

.bs-cad-id { flex: 1; min-width: 0; }
.bs-cad-nome {
  font-size: 13px; font-weight: 600; color: var(--text);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.bs-cad-fonte {
  display: flex; align-items: center; gap: 6px;
  margin-top: 2px; font-size: 11px; color: var(--text-muted);
}
.bs-cad-fonte span { width: 6px; height: 6px; flex-shrink: 0; border-radius: 999px; background: var(--cor); }

.bs-cad-badge {
  flex-shrink: 0; padding: 2px 8px; border-radius: 6px;
  font-family: var(--fonte-mono); font-size: 10px; font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--cor-b); background: color-mix(in srgb, var(--cor-b) 15%, transparent);
}
.bs-b-erro { --cor-b: var(--danger); }
.bs-b-esp { --cor-b: var(--warning); }

/* Os dois botões dividem a linha em partes iguais: decidir e agir custam o
   mesmo clique, e a fila anda mais rápido sem hierarquia entre eles. */
.bs-cad-acoes { display: flex; gap: 6px; }
.bs-btn {
  flex: 1; display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  padding: 8px; border-radius: 8px;
  font-family: var(--fonte); font-size: 11px; font-weight: 600; text-decoration: none;
}
.bs-btn-ic { width: 12px; height: 12px; }
.bs-btn-sec { border: 1px solid var(--border); background: var(--bg-card); color: var(--text); }
.bs-btn-pri { border: 1px solid transparent; background: var(--accent); color: var(--bg-base); }
.bs-btn-sec:hover { border-color: var(--accent); color: var(--text); }
.bs-btn-pri:hover { background: #38bdf8; }
